/**
 * Editorial manifest — the part of the project index that is curated by hand.
 *
 * Order, featured status, category, status and links live here; prose lives in
 * messages/{locale}.json under `projects.items.<slug>`. Repository metadata (language,
 * last push, CI, tests…) is merged in from src/data/github.json, which is regenerated by
 * `pnpm sync:github` and never edited by hand.
 *
 * A repository discovered by the sync is never promoted here automatically: it only shows
 * up in the "other public repositories" list until it is added to this file.
 */

/** Evidence status. Drives the ●/◐/○ glyph used everywhere on the site. */
export type Status = 'built' | 'progress' | 'planned';

export type Project = {
  slug: string;
  /** Entry number in the journal. */
  no: string;
  /** Anchor of the long-form case study, when the entry has one. */
  anchor?: string;
  status: Status;
  years: string;
  /** Public repository name under the GitHub user. Omit for private / non-code work. */
  repo?: string;
  /** Why there is no repository link, when there is none. */
  visibility?: 'private' | 'proprietary';
  demo?: string;
};

